# (section ID, translated heading, translated body, optional code)
def section(ident,title,body,code=None):return {'id':ident,'title':title,'body':body,'code':code}
PAGES=[
 {'slug':'getting-started','group':'getting','title':T('Quick start','Быстрый старт','Tez boshlash'),
  'description':T('From a fresh installation to a configured dashboard.','От установки до настроенной панели управления.','O‘rnatishdan sozlangan boshqaruv paneligacha.'),
  'sections':[
   section('before',T('Before you begin','Перед началом','Boshlashdan oldin'),T('You need Python 3.10+, Docker with Compose 2.24+, a MetaTrader 5 account and Telegram access. Start with a demo broker account. AI provider access is configured in the dashboard.','Нужны Python 3.10+, Docker с Compose 2.24+, счёт MetaTrader 5 и доступ к Telegram. Начните с демосчёта брокера. AI-провайдер настраивается в панели.','Python 3.10+, Compose 2.24+ bilan Docker, MetaTrader 5 hisobi va Telegram kerak. Broker demo hisobidan boshlang. AI provayderi panelda sozlanadi.')),
   section('install',T('Install the CLI','Установите CLI','CLI o‘rnating'),T('Copy the command for your computer from the home page. It installs the lvct command and public source, without starting containers. The optional Python flag installs Python where the operating system installer is supported.','Скопируйте команду своей ОС с главной страницы. Она устанавливает команду lvct и публичные исходники, не запуская контейнеры. Флаг установки Python работает там, где поддерживается установщик ОС.','Bosh sahifada tizimingiz uchun buyruqni nusxalang. U lvct buyrug‘i va ochiq manbani o‘rnatadi, konteynerlarni ishga tushirmaydi. Python o‘rnatish bayrog‘i qo‘llab-quvvatlangan OS o‘rnatuvchisidan foydalanadi.'),'lvct --help\nlvct deps\nlvct deps --install'),
   section('configure',T('Create your installation','Создайте установку','Muhitni sozlang'),T('The wizard asks for a dashboard username/password and broker server/login/password. Telegram API ID and hash are optional here. Encryption and RPC keys are generated automatically. Existing configurations are never overwritten.','Мастер спросит имя и пароль панели, сервер, логин и пароль брокера. Telegram API ID и hash можно добавить позже. Ключи шифрования и RPC создаются автоматически. Готовая конфигурация не перезаписывается.','Usta panel login/parolini va broker server/login/parolini so‘raydi. Telegram API ID va hash’ni keyin ham qo‘shish mumkin. Shifrlash va RPC kalitlari avtomatik yaratiladi. Mavjud sozlamalar ustiga yozilmaydi.'),'lvct init\nlvct doctor\nlvct start\nlvct open --settings'),
   section('connect',T('Connect, review, then arm','Подключите, проверьте, включите','Ulang, tekshiring, so‘ng yoqing'),T('In Settings connect Telegram, select a signal channel, configure an AI provider and review the broker account and risk limits. Starting containers does not arm trading. Arm only after reviewing these settings. The first Wine/MT5 build can exceed 40 minutes; startup takes several more minutes.','В Settings подключите Telegram, выберите канал сигналов, настройте AI-провайдера, проверьте брокерский счёт и лимиты риска. Запуск контейнеров не включает торговлю. Включайте её после проверки настроек. Первая сборка Wine/MT5 может занять больше 40 минут, начальный запуск — ещё несколько минут.','Settings’da Telegram’ni ulang, signal kanalini tanlang, AI provayderini sozlang, broker hisobi va xavf limitlarini tekshiring. Konteynerlar ishga tushishi savdoni yoqmaydi. Sozlamalarni tekshirgach yoqing. Birinchi Wine/MT5 yig‘ilishi 40 daqiqadan oshishi, ishga tushish esa yana bir necha daqiqa olishi mumkin.')),
  ]},
 {'slug':'platforms','group':'getting','title':T('Platforms & requirements','Платформы и требования','Platformalar va talablar'),
  'description':T('Choose the right runtime for your computer.','Выберите runtime для своего компьютера.','Kompyuteringiz uchun mos runtime tanlang.'),
  'sections':[
   section('linux',T('Linux x64','Linux x64','Linux x64'),T('Use Docker Engine with the Compose plugin. The CLI runs on Python 3.10 or newer. The managed local trading runtime requires a Linux amd64 engine. Allocate at least 4 GiB to Docker for builds; 8 GiB or more is a practical starting point for the computer.','Используйте Docker Engine с плагином Compose и Python 3.10+. Локальному торговому runtime нужен Linux amd64. Для сборок выделите Docker хотя бы 4 GiB; для компьютера разумно иметь от 8 GiB RAM.','Compose plaginli Docker Engine va Python 3.10+ ishlating. Lokal savdo runtime’i Linux amd64 talab qiladi. Yig‘ish uchun Docker’ga kamida 4 GiB, kompyuterga esa 8 GiB yoki ko‘proq RAM tavsiya etiladi.')),
   section('windows',T('Windows x64','Windows x64','Windows x64'),T('Use PowerShell, Python 3.10+ and Docker Desktop with Linux containers / WSL 2. Complete Docker Desktop’s first-run setup before doctor. CLI portability is tested separately from native desktop broker execution.','Нужны PowerShell, Python 3.10+ и Docker Desktop с Linux-контейнерами / WSL 2. Пройдите начальную настройку Docker Desktop перед doctor. Переносимость CLI проверяется отдельно от исполнения брокерских сделок на desktop.','PowerShell, Python 3.10+ va Linux konteynerlari / WSL 2 bilan Docker Desktop kerak. Doctor’dan oldin Docker Desktop’ning dastlabki sozlamalarini yakunlang. CLI mosligi desktop’da broker buyruqlarini bajarishdan alohida tekshiriladi.')),
   section('mac',T('macOS: Intel & Apple Silicon','macOS: Intel и Apple Silicon','macOS: Intel va Apple Silicon'),T('Intel Macs can use Docker Desktop locally. Apple Silicon uses the CLI on the Mac and a Linux x64 Docker host over SSH. Local ARM emulation is not part of the managed installer. The existing Linux ARM/FEX deployment has a separate advanced runbook.','Intel Mac может использовать локальный Docker Desktop. На Apple Silicon CLI работает на Mac, а Linux x64 Docker-host подключается по SSH. Локальная ARM-эмуляция не входит в установщик. Для существующей Linux ARM/FEX-схемы есть отдельное расширенное руководство.','Intel Mac lokal Docker Desktop ishlatishi mumkin. Apple Silicon’da CLI Mac’da ishlaydi, Linux x64 Docker host esa SSH orqali ulanadi. Lokal ARM emulyatsiyasi o‘rnatuvchiga kirmaydi. Mavjud Linux ARM/FEX muhiti uchun alohida kengaytirilgan qo‘llanma bor.')),
   section('local-mac',T('Local Apple Silicon: current status','Локальный Apple Silicon: текущий статус','Lokal Apple Silicon: hozirgi holat'),T('MetaQuotes supports the MT5 application on Apple M1 and newer. Our automatic local Mac runtime still needs implementation and testing of the Python SDK, RPC bridge and recovery. The Ubuntu ARM/FEX setup uses Linux host libraries and has not been validated on macOS. CLI unit tests do not establish local MT5 compatibility.','MetaQuotes поддерживает приложение MT5 на Apple M1 и новее. Нашему локальному Mac-runtime ещё нужны реализация и проверка Python SDK, RPC и восстановления. Ubuntu ARM/FEX использует Linux-библиотеки хоста и не проверен на macOS. Unit-тесты CLI не доказывают локальную совместимость MT5.','MetaQuotes MT5 ilovasini Apple M1 va yangiroq chiplarda qo‘llaydi. Bizning lokal Mac runtime’imiz uchun Python SDK, RPC va tiklanishni ishlab chiqish va sinash kerak. Ubuntu ARM/FEX hostning Linux kutubxonalaridan foydalanadi va macOS’da tekshirilmagan. CLI unit testlari lokal MT5 mosligini isbotlamaydi.')),
   section('ssh',T('Remote engine over SSH','Удалённый Docker по SSH','SSH orqali masofaviy Docker'),T('Supply your own existing Linux x64 computer or VPS and its SSH address. Server hosting is arranged separately. The host needs Docker, Compose, Python 3 and SSH key access with Docker privileges. Your computer needs the Docker CLI, Compose and OpenSSH. LVCT creates its own context and leaves the global context unchanged. Keep open running to maintain the private panel tunnel.','Укажите адрес своего существующего Linux x64 компьютера или VPS. Размещение сервера организуется отдельно. Нужны Docker, Compose, Python 3 и SSH-доступ по ключу с правами Docker. На компьютере — Docker CLI, Compose и OpenSSH. LVCT создаёт свой контекст. Команда open держит приватный туннель панели, пока открыта.','O‘zingizning mavjud Linux x64 kompyuteringiz yoki VPS va SSH manzilini taqdim eting. Hosting alohida tashkil qilinadi. Hostda Docker, Compose, Python 3 va Docker huquqli SSH kaliti kerak. Kompyuterda Docker CLI, Compose va OpenSSH bo‘lishi lozim. LVCT alohida kontekst yaratadi. Open buyrug‘i ochiq turguncha panelning xususiy tunnelini saqlaydi.'),'lvct init --remote user@server.example\nlvct doctor\nlvct start\nlvct open'),
  ]},
 {'slug':'configuration','group':'getting','title':T('Configuration','Настройка','Sozlamalar'),
  'description':T('Private credentials, dashboard access and local ports.','Приватные данные, доступ к панели и локальные порты.','Maxfiy ma’lumotlar, panelga kirish va lokal portlar.'),
  'sections':[
   section('ports',T('A port of your own','Отдельный порт','Alohida port'),T('New CLI installations choose the first free loopback port from 19471 to 19570. An explicit --port selects one port and refuses a collision. SSH installs probe the remote host. Existing installations retain their configured port; manual Compose keeps its legacy default.','Новая CLI-установка ищет свободный loopback-порт от 19471 до 19570. Флаг --port задаёт конкретный порт и отказывает при занятости. Для SSH проверяется сервер. Старые установки сохраняют порт; ручной Compose сохраняет прежний default.','Yangi CLI o‘rnatilishi 19471–19570 oralig‘idan bo‘sh loopback port izlaydi. --port aniq portni belgilaydi va band bo‘lsa rad etadi. SSH holatida server tekshiriladi. Mavjud muhitlar o‘z portini, qo‘lda Compose esa eski standartini saqlaydi.'),'lvct init --port 20471\nlvct config'),
   section('password',T('Change the dashboard password','Смените пароль панели','Panel parolini almashtiring'),T('Use password on a running app. The new password is prompted privately and old sessions are invalidated without restarting trading. Docker owner access is required. The initial environment password remains a bootstrap value; the protected data-volume override takes priority.','Команда password работает при запущенном приложении. Пароль вводится скрыто, старые сессии аннулируются без перезапуска торговли. Нужны права владельца Docker. Исходный пароль env остаётся bootstrap-значением; приоритет имеет защищённый override в data volume.','Password buyrug‘i ishlayotgan ilovada bajariladi. Yangi parol yashirin kiritiladi, eski sessiyalar savdoni qayta ishga tushirmasdan bekor qilinadi. Docker egasi huquqi kerak. Dastlabki env paroli boshlang‘ich qiymat bo‘lib qoladi, data volume’dagi himoyalangan qiymat ustuvor.'),'lvct password\nlvct password --username operator'),
   section('storage',T('Where your settings live','Где хранятся настройки','Sozlamalar qayerda saqlanadi'),T('The CLI keeps private runtime.env and installation.json outside the source checkout. Linux uses ~/.local/share/lvct, macOS uses ~/Library/Application Support/lvct, Windows uses %LOCALAPPDATA%\\lvct. Back up this configuration together with Docker data/MT5 volumes and the original encryption key. Never publish runtime files.','CLI хранит runtime.env и installation.json вне исходников: Linux — ~/.local/share/lvct, macOS — ~/Library/Application Support/lvct, Windows — %LOCALAPPDATA%\\lvct. Резервируйте конфигурацию вместе с Docker-томами data/MT5 и исходным ключом шифрования. Не публикуйте runtime-файлы.','CLI runtime.env va installation.json’ni manbadan tashqarida saqlaydi: Linux — ~/.local/share/lvct, macOS — ~/Library/Application Support/lvct, Windows — %LOCALAPPDATA%\\lvct. Ularni Docker data/MT5 volume’lari va asl shifrlash kaliti bilan birga zaxiralang. Runtime fayllarini oshkor qilmang.')),
  ]},
 {'slug':'commands','group':'operate','title':T('CLI reference','Команды CLI','CLI buyruqlari'),
  'description':T('Everyday commands, their effect and completion behaviour.','Повседневные команды, их действие и время выполнения.','Kundalik buyruqlar, ularning vazifasi va bajarilishi.'),
  'sections':[
   section('lifecycle',T('Start, inspect, stop','Запуск, состояние, остановка','Ishga tushirish, holat, to‘xtatish'),T('Start retains running containers. Stop and restart ask for confirmation because position management pauses. They do not close broker positions or remove broker-side SL/TP. The CLI has no test-order command.','Start сохраняет работающие контейнеры. Stop и restart запрашивают подтверждение: управление позициями приостанавливается. Они не закрывают позиции у брокера и не снимают брокерские SL/TP. Команды тестового ордера в CLI нет.','Start ishlayotgan konteynerlarni saqlaydi. Stop va restart pozitsiya boshqaruvini to‘xtatgani uchun tasdiq so‘raydi. Ular broker pozitsiyalarini yopmaydi va brokerdagi SL/TP’ni olib tashlamaydi. CLI’da sinov orderi buyrug‘i yo‘q.'),'lvct start\nlvct status --json\nlvct open\nlvct stop\nlvct restart'),
   section('inspect',T('Health and logs','Здоровье и логи','Holat va loglar'),T('Doctor checks dependencies and configuration. Health checks component readiness. Errors groups recent failures with guidance. Logs can filter severity, service, time and text. JSON output is available for automation.','Doctor проверяет зависимости и конфигурацию, health — готовность компонентов. Errors группирует ошибки с подсказками. Logs фильтрует уровень, сервис, время и текст. Для автоматизации есть JSON.','Doctor bog‘liqliklar va sozlamalarni, health esa komponentlar tayyorligini tekshiradi. Errors xatolarni ko‘rsatmalar bilan guruhlaydi. Logs daraja, servis, vaqt va matn bo‘yicha filtrlaydi. Avtomatlashtirish uchun JSON mavjud.'),'lvct doctor --json\nlvct health --json\nlvct errors --since 2h --json\nlvct logs --service app --level error --since 30m\nlvct logs --level critical --contains timeout'),
   section('durations',T('Commands that stay open','Длительные команды','Uzoq ishlaydigan buyruqlar'),T('logs -f, health --watch and remote open stay in the foreground until Ctrl+C. Builds can exceed 40 minutes on first installation. Do not interrupt a healthy build with a short automation timeout. Most bounded diagnostic calls take seconds, but Docker/SSH checks can total several minutes.','Logs -f, health --watch и удалённый open работают до Ctrl+C. Первая сборка может занять больше 40 минут. Не обрывайте исправную сборку коротким таймаутом агента. Обычные проверки занимают секунды, но Docker/SSH могут потребовать несколько минут.','Logs -f, health --watch va masofaviy open Ctrl+C gacha ishlaydi. Birinchi yig‘ilish 40 daqiqadan oshishi mumkin. To‘g‘ri ishlayotgan yig‘ishni qisqa avtomatlashtirish taymauti bilan uzmang. Oddiy tekshiruvlar soniyalar, Docker/SSH tekshiruvlari bir necha daqiqa olishi mumkin.'),'lvct logs -f --service app\nlvct health --watch --interval 10'),
  ]},
 {'slug':'troubleshooting','group':'operate','title':T('Troubleshooting','Диагностика ошибок','Xatolarni aniqlash'),
  'description':T('Find the cause before changing the runtime.','Найдите причину до изменения runtime.','Runtime’ni o‘zgartirishdan oldin sababini toping.'),
  'sections':[
   section('triage',T('Follow the evidence','Проверяйте по шагам','Bosqichma-bosqich tekshiring'),T('Begin with doctor, then status, health and errors. A running container is not proof of broker readiness. Health separates MT5, Telegram and AI provider status. Degraded health returns exit code 1 as well as unhealthy state.','Начните с doctor, затем status, health и errors. Запущенный контейнер не доказывает готовность брокера. Health разделяет MT5, Telegram и AI. И degraded, и unhealthy возвращают код 1.','Doctor’dan boshlang, keyin status, health va errors. Ishlayotgan konteyner broker tayyorligini isbotlamaydi. Health MT5, Telegram va AI holatini alohida ko‘rsatadi. Degraded va unhealthy holatlari 1 kodini qaytaradi.'),'lvct doctor\nlvct health\nlvct errors --since 1h'),
   section('causes',T('Common causes','Частые причины','Ko‘p uchraydigan sabablar'),T('IPC/terminal errors: inspect sidecar logs and the broker server selection. Algo Trading errors: check terminal and broker permissions. Provider errors: check model, credentials and credit. Telegram FloodWait: respect its delay. Storage/decryption errors: check disk access and the original key; do not delete the database.','Ошибки IPC/терминала: проверьте логи sidecar и выбор сервера брокера. Algo Trading: разрешения терминала и брокера. AI: модель, ключ и баланс. Telegram FloodWait: выдержите паузу. Хранилище/дешифрование: проверьте диск и исходный ключ; не удаляйте базу.','IPC/terminal xatosi: sidecar loglari va broker serverini tekshiring. Algo Trading: terminal va broker ruxsatlarini tekshiring. AI: model, kalit va balansni tekshiring. Telegram FloodWait: belgilangan muddatni kuting. Saqlash/deshifrlash: disk va asl kalitni tekshiring, bazani o‘chirmang.')),
   section('critical',T('Critical error context','Критичные ошибки и контекст','Jiddiy xatolar va tafsilotlar'),T('ERROR includes failures; CRITICAL/FATAL is a stricter filter. Traceback lines stay with the matching error. CLI failures are retained in a bounded private logs/cli.jsonl journal. If Docker is unavailable, errors still shows recent CLI failures. Do not blindly repeat an ambiguous broker action.','ERROR включает ошибки, CRITICAL/FATAL — более строгий фильтр. Traceback сохраняется вместе с ошибкой. Сбои CLI записываются в приватный ограниченный logs/cli.jsonl. Даже без Docker errors показывает последние сбои CLI. Не повторяйте брокерское действие с неизвестным результатом.','ERROR xatolarni, CRITICAL/FATAL esa eng jiddiylarini ko‘rsatadi. Traceback tegishli xato bilan saqlanadi. CLI xatolari cheklangan xususiy logs/cli.jsonl jurnaliga yoziladi. Docker ishlamasa ham errors oxirgi CLI xatolarini ko‘rsatadi. Natijasi noaniq broker amalini ko‘r-ko‘rona takrorlamang.'),'lvct logs --level critical --since 1d\nlvct logs --service mt5-sidecar --level error --tail 300'),
  ]},
 {'slug':'updates','group':'operate','title':T('Updates & rollback','Обновление и откат','Yangilash va qaytarish'),
  'description':T('Plan maintenance without surprise trading restarts.','Плановое обслуживание с контролируемым запуском.','Ishga tushirishni nazorat qilgan holda rejalangan xizmat.'),
  'sections':[
   section('check',T('Check first','Сначала проверка','Avval tekshiring'),T('Update without flags checks the official public repository. It never stops or restarts services. Preview downloads can be ahead of GitHub; the CLI will say if the public revision does not yet include compatible update support.','Update без флагов проверяет официальный публичный репозиторий и не останавливает сервисы. Preview-загрузка может опережать GitHub: CLI сообщит, если публичный commit ещё не содержит совместимый механизм обновления.','Bayroqsiz update rasmiy ochiq repozitoriyni tekshiradi, servislarni to‘xtatmaydi. Dastlabki yuklama GitHub’dan oldinda bo‘lishi mumkin: ochiq commit mos yangilashni qo‘llamasa, CLI aytadi.'),'lvct update --check'),
   section('apply',T('Apply during a planned stop','Установка во время обслуживания','Rejalangan to‘xtashda o‘rnatish'),T('Review positions and back up volumes before maintenance. Apply refuses running/paused services, builds new images and creates stopped containers. Credentials, installation identity and volumes remain. It does not start the new version automatically.','Проверьте позиции и сделайте резервную копию томов. Apply отказывает при работающих/приостановленных сервисах, собирает образы и создаёт остановленные контейнеры. Ключи, идентификатор и тома сохраняются. Новая версия автоматически не запускается.','Xizmatdan oldin pozitsiyalarni tekshiring va volume’larni zaxiralang. Apply ishlayotgan/pauzadagi servislarni rad etadi, yangi obrazlar va to‘xtatilgan konteynerlar yaratadi. Kalitlar, muhit identifikatori va volume’lar saqlanadi. Yangi versiya avtomatik ishga tushmaydi.'),'lvct stop\nlvct update --apply\nlvct doctor\nlvct start'),
   section('rollback',T('Recover an interrupted update','Восстановление после прерывания','Uzilgan yangilashni tiklash'),T('Run rollback while services are stopped. It restores previous source, CLI and image tags, and leaves services stopped. Do not delete maintenance.json or prune rollback images. Rollback does not undo database migrations performed after starting a newer version; that needs your backup.','Запустите rollback при остановленных сервисах. Он восстановит исходники, CLI и образы, оставив сервисы остановленными. Не удаляйте maintenance.json и rollback-образы. Откат не отменяет миграции базы после запуска новой версии — для них нужна резервная копия.','Servislar to‘xtatilganda rollback bajaring. U oldingi manba, CLI va obrazlarni tiklaydi va servislarni to‘xtatilgan holda qoldiradi. Maintenance.json va rollback obrazlarini o‘chirmang. Qaytarish yangi versiya ishga tushirgandan keyingi baza migratsiyasini bekor qilmaydi — buning uchun zaxira kerak.'),'lvct update --rollback'),
  ]},
 {'slug':'support','group':'reference','title':T('Support reports','Отчёты в поддержку','Yordamga hisobotlar'),
  'description':T('Review locally. Send only when you choose.','Сначала просмотрите. Отправьте по своему решению.','Avval ko‘rib chiqing. Xohlasangiz yuboring.'),
  'sections':[
   section('create',T('Create a private report','Создайте приватный отчёт','Xususiy hisobot yarating'),T('Report saves JSON locally and prints its path. It includes platform/version, component readiness and bounded recent error text. It works even before setup. It does not attach environment files, databases, broker files, positions or trade history.','Report сохраняет JSON локально и печатает путь. В нём — версия/платформа, состояние компонентов и ограниченные последние ошибки. Команда работает и до настройки. Env, база, брокерские файлы, позиции и история сделок не прикладываются.','Report JSON’ni lokal saqlaydi va yo‘lini ko‘rsatadi. Unda versiya/platforma, komponentlar holati va cheklangan oxirgi xatolar bo‘ladi. Sozlashdan oldin ham ishlaydi. Env, baza, broker fayllari, pozitsiyalar va savdo tarixi biriktirilmaydi.'),'lvct report --note "Describe the problem"'),
   section('send',T('Review and send','Просмотрите и отправьте','Ko‘rib chiqib yuboring'),T('Open the saved JSON first. Redaction removes known secrets and common identifiers, but arbitrary text needs your review. Sending is explicit and confirmed. Optional --contact EMAIL includes a reply address. Acceptance means saved/queued, not that owner notifications have already arrived.','Откройте JSON перед отправкой. Маскирование удаляет известные ключи и типичные идентификаторы, но произвольный текст нужно проверить. Отправка явная, с подтверждением. Флаг --contact EMAIL добавляет адрес для ответа. Принятие сервером означает сохранение/очередь, а не доставку уведомлений.','Yuborishdan oldin JSON’ni oching. Tozalash ma’lum kalitlar va odatiy identifikatorlarni yashiradi, ammo ixtiyoriy matnni o‘zingiz tekshiring. Yuborish aniq tasdiqlanadi. --contact EMAIL javob manzilini qo‘shadi. Server qabul qilishi xabarnoma yetib borganini emas, saqlanganini/navbatga qo‘yilganini bildiradi.'),'lvct report --send --file PATH_TO_REPORT'),
   section('privacy',T('Retention and delivery','Хранение и доставка','Saqlash va yetkazish'),T('The official support server encrypts reports, retains them for up to 14 days and notifies the owner by Telegram and email. IPs are stored as keyed hashes. There is no public inbox-reading endpoint. Limits are 3 reports/hour per IP and 20/day globally. A 429 means wait; keep the same report file for retries.','Официальный сервер шифрует отчёты, хранит до 14 дней и уведомляет владельца в Telegram и по почте. IP сохраняются в виде хешей с ключом. Публичного доступа к отчётам нет. Лимиты: 3 отчёта/час на IP и 20/день суммарно. При 429 подождите; повторяйте отправку того же файла.','Rasmiy server hisobotlarni shifrlab, 14 kungacha saqlaydi va egasiga Telegram hamda email orqali xabar beradi. IP’lar kalitli xesh sifatida saqlanadi. Ommaviy o‘qish API’i yo‘q. Cheklov: IP uchun soatiga 3 ta, jami kuniga 20 ta hisobot. 429 bo‘lsa kuting va o‘sha fayldan qayta foydalaning.')),
  ]},
 {'slug':'agents','group':'reference','title':T('For AI agents','Для AI-агентов','AI agentlari uchun'),
  'description':T('Safe automation and predictable command contracts.','Безопасная автоматизация и контракты команд.','Xavfsiz avtomatlashtirish va buyruq qoidalari.'),
  'sections':[
   section('read',T('Read before acting','Прочитайте перед действием','Amaldan oldin o‘qing'),T('Read AGENTS.md and docs/CLI-AGENTS.md in the selected source. Select the correct --home for the installation. Start with --help and read-only JSON diagnostics. Do not adopt a manually configured owner deployment or run a duplicate live runtime against its account/session.','Прочитайте AGENTS.md и docs/CLI-AGENTS.md выбранного исходника. Выберите правильный --home. Начните с --help и read-only JSON-проверок. Не подключайте ручную установку владельца и не создавайте второй live runtime с тем же счётом/сессией.','Tanlangan manbadagi AGENTS.md va docs/CLI-AGENTS.md’ni o‘qing. Muhit uchun to‘g‘ri --home tanlang. --help va faqat o‘qish JSON tekshiruvlaridan boshlang. Eganing qo‘lda sozlangan muhitini o‘zlashtirmang va shu hisob/sessiya bilan ikkinchi jonli runtime yaratmang.'),'lvct --help\nlvct doctor --json\nlvct health --json\nlvct errors --since 1h --json'),
   section('codes',T('Exit codes and time budgets','Коды возврата и таймауты','Natija kodlari va vaqt'),T('0: command/check completed; 1: failed or degraded health; 2: invalid arguments; 130: Ctrl+C. Errors returns 0 after a successful read even when errors exist. Runtime log unavailability returns 1 while showing local CLI events. Keep long build sessions alive; logs -f, health --watch and SSH open are intentionally persistent.','0 — команда/проверка выполнена; 1 — сбой или degraded health; 2 — неверные аргументы; 130 — Ctrl+C. Errors возвращает 0 после чтения даже при найденных ошибках. Недоступность runtime-логов даёт 1 с показом локальных событий. Держите длительные сборки открытыми; logs -f, health --watch и SSH open постоянны по замыслу.','0 — buyruq/tekshiruv tugadi; 1 — xato yoki degraded holati; 2 — noto‘g‘ri argument; 130 — Ctrl+C. Errors o‘qish muvaffaqiyatli bo‘lsa, xatolar mavjudligida ham 0 qaytaradi. Runtime loglari yo‘q bo‘lsa, lokal hodisalar bilan 1 qaytaradi. Uzoq yig‘ilish sessiyalarini saqlang; logs -f, health --watch va SSH open ataylab doimiy.')),
   section('boundaries',T('Explicit actions','Явные действия','Aniq amallar'),T('Do not send a broker order to test connectivity, regenerate an encryption key, delete volumes or blindly retry an ambiguous trade. Stop/restart and support uploads require user authorization. --yes confirms authorization already given; it does not create permission. Never print raw environment, Docker inspect secrets, sessions or broker credentials.','Не проверяйте подключение ордером, не регенерируйте ключ шифрования, не удаляйте тома и не повторяйте сделку с неизвестным результатом. Stop/restart и отправка отчётов требуют разрешения пользователя. --yes подтверждает уже полученное разрешение. Не печатайте env, секреты Docker inspect, сессии и данные брокера.','Ulanishni order bilan sinamang, shifrlash kalitini yangidan yaratmang, volume’larni o‘chirmang va natijasi noaniq savdoni takrorlamang. Stop/restart va hisobot yuborish foydalanuvchi ruxsatini talab qiladi. --yes oldindan berilgan ruxsatni tasdiqlaydi, o‘zi ruxsat bermaydi. Env, Docker inspect sirlarini, sessiyalar va broker ma’lumotlarini chiqarmang.')),
  ]},
]
